<script setup lang="ts">
import WalletSubmittedProofs from './WalletSubmittedProofs.vue'
import {computed,watch} from 'vue'
import {useI18n} from 'vue-i18n'
import PaymentProofUpload from '../../../components/payment/PaymentProofUpload.vue'
import {useWalletPayNowProof} from './useWalletPayNowProof'
import type {ProofContext} from './types'
const props=defineProps<{store:string;sourceType:string;sourceId:string;channel:string;amount:string;disabled:boolean}>()
const emit=defineEmits<{change:[state:{proofId?:string;bankReference?:string;context:ProofContext|null;blocked:boolean}]}>()
const {t}=useI18n(),input=computed(()=>({store:props.store,sourceType:props.sourceType,sourceId:props.sourceId,channel:props.channel,amount:props.amount}))
const {context,proof,file,busy,loading,error,select,scan,refresh,adopt}=useWalletPayNowProof(input)
watch([context,proof,file,busy,loading,error],()=>emit('change',{context:context.value,proofId:proof.value?.id,bankReference:proof.value?.bankReference??undefined,blocked:loading.value||busy.value||!context.value||!!file.value&&!proof.value||!!proof.value&&Object.values(proof.value.checks).includes('mismatch')}),{immediate:true})
</script>
<template><section class="wallet-paynow-proof"><p v-if="loading" role="status">{{t('wallet.loading')}}</p><dl v-if="context" class="wallet-detail-fields"><dt>{{t('wallet.proof.systemReference')}}</dt><dd><code>{{context.systemReference}}</code></dd><dt>{{t('wallet.proof.expectedAccount')}}</dt><dd>{{context.merchantName}} · {{context.expectedAccount}}</dd></dl><WalletSubmittedProofs :store="store" :source-type="sourceType" :source-id="sourceId" :channel="channel" :amount="amount" :disabled="disabled||busy||loading||!context" @select="adopt" /><p>{{t('wallet.proof.optionalHint')}}</p><PaymentProofUpload accept="image/png,image/jpeg" :model-value="file" :disabled="disabled||busy" :max-bytes="5*1024*1024" :capture-label="t('wallet.proof.capture')" :album-label="t('wallet.proof.album')" :empty-label="t('wallet.proof.noFile')" :remove-label="t('wallet.proof.remove')" :invalid-label="t('wallet.proof.invalidImage')" @update:model-value="select" /><button v-if="file" type="button" :disabled="disabled||busy||!context" @click="scan">{{t(busy?'wallet.proof.scanning':'wallet.proof.scan')}}</button><p v-if="error" class="wallet-error" role="alert">{{error}} <button v-if="!context" type="button" :disabled="loading" @click="refresh">{{t('wallet.refresh')}}</button></p><template v-if="proof"><a v-if="!file" :href="proof.imageUrl" target="_blank" rel="noopener">{{t('wallet.proof.view')}}</a><p v-if="proof.extracted.ocrStatus==='unavailable'" class="wallet-warning">{{t('wallet.proof.ocrUnavailable')}}</p><p v-if="proof.bankReference">{{t('wallet.proof.bankReference')}}: {{proof.bankReference}}</p><dl class="wallet-detail-fields"><template v-for="(result,field) in proof.checks" :key="field"><dt>{{t('wallet.proof.'+field)}}</dt><dd :class="{'wallet-error':result==='mismatch'}">{{t('wallet.proof.'+result)}}</dd></template></dl><p>{{t('wallet.proof.attestationHint')}}</p></template></section></template>
<style scoped>.wallet-paynow-proof{border:1px solid #dce4ef;border-radius:16px;padding:14px}.wallet-paynow-proof code{overflow-wrap:anywhere}.wallet-paynow-proof p{font-size:13px;color:#61718b}</style>
